  if (!entry) {
    const known = index.map((s) => s.name).join(", ");
    throw new SkillApiError(`unknown skill ${JSON.stringify(name)} - the registry has: ${known}`);
  }
  const url = entry.url.startsWith("http") ? entry.url : `${base}${entry.url}`;
  let res;
